package com.enjoyyourtime.globalfitness.food

import com.enjoyyourtime.globalfitness.R
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The food catalog asset (generated by tools/food-db) keeps the contract the app reads: columns, numbers, groups,
 * portion keys, and a `food_<id>` name in English and Spanish for every food. Plain parsing on purpose, independent
 * of the app's own parser.
 */
class FoodsTsvContractTest {
    private val header = listOf(
        "id", "group", "unit", "kcal", "protein", "carbs", "sugars", "fat", "sat_fat", "fiber", "salt", "portion",
        "portions", "visual", "source",
    )
    private val groups = setOf(
        "fruit", "vegetables", "grains", "legumes", "meat", "fish", "eggs", "dairy", "fats_nuts", "sweets", "drinks",
        "dishes", "fast_food", "snacks", "sauces",
    )
    private val portionKeys = setOf(
        "unit", "piece", "slice", "plate", "small_plate", "bowl", "cup", "glass", "can", "bottle", "tbsp", "tsp",
        "handful", "serving",
    )

    private fun findRepoFile(path: String): File? =
        generateSequence(File(System.getProperty("user.dir")).absoluteFile) { it.parentFile }
            .map { File(it, path) }
            .firstOrNull { it.isFile }

    private fun repoFile(path: String): File = findRepoFile(path).also { assertNotNull(path, it) }!!

    private val text = repoFile("app/src/main/assets/food/foods.tsv").readText(Charsets.UTF_8)
    private val lines = text.split('\n').dropLastWhile { it.isEmpty() }
    private val rows = lines.drop(1).map { line -> header.zip(line.split('\t')).toMap() }

    @Test
    fun headerAndColumns() {
        assertTrue("LF line endings", '\r' !in text)
        assertEquals(header, lines.first().split('\t'))
        for (line in lines.drop(1)) assertEquals(line, header.size, line.split('\t').size)
        assertTrue("${rows.size} foods", rows.size >= 250)
    }

    @Test
    fun idsGroupsUnitsAndSources() {
        val ids = rows.map { it.getValue("id") }
        assertEquals("duplicate ids", ids.size, ids.toSet().size)
        for (r in rows) {
            val id = r.getValue("id")
            assertTrue(id, Regex("[a-z0-9_]+").matches(id))
            assertTrue("$id group", r.getValue("group") in groups)
            assertTrue("$id unit", r.getValue("unit") in setOf("g", "ml"))
            assertTrue("$id visual", r.getValue("visual") in setOf("0", "1"))
            assertTrue("$id source", Regex("(fdc|ciqual):\\d+|recipe").matches(r.getValue("source")))
        }
    }

    @Test
    fun nutrientsAreNumbersPer100() {
        for (r in rows) {
            val id = r.getValue("id")
            assertTrue("$id kcal", Regex("\\d+").matches(r.getValue("kcal")))
            val v = listOf("protein", "carbs", "sugars", "fat", "sat_fat", "fiber", "salt").associateWith { k ->
                val s = r.getValue(k)
                if (s.isEmpty()) {
                    assertTrue("$id $k may be empty only for sugars/sat_fat/fiber/salt", k !in setOf("protein", "carbs", "fat"))
                    null
                } else {
                    assertTrue("$id $k = $s", Regex("\\d+(\\.\\d)?").matches(s))
                    s.toDouble()
                }
            }
            val kcal = r.getValue("kcal").toDouble()
            assertTrue("$id kcal $kcal", kcal <= 900)
            val solids = listOf("protein", "carbs", "fat", "fiber", "salt").sumOf { v[it] ?: 0.0 }
            assertTrue("$id: $solids g of nutrients per 100", solids <= 101)
            v["sugars"]?.let { assertTrue("$id sugars <= carbs", it <= v.getValue("carbs")!! + 0.15) }
            v["sat_fat"]?.let { assertTrue("$id saturated fat <= fat", it <= v.getValue("fat")!! + 0.15) }
        }
    }

    @Test
    fun portionsUseTheFixedKeys() {
        for (r in rows) {
            val id = r.getValue("id")
            val portion = r.getValue("portion").toIntOrNull()
            assertTrue("$id portion", portion != null && portion > 0)
            val portions = r.getValue("portions").takeIf { it.isNotEmpty() }?.split('|').orEmpty().map { part ->
                val (key, amount) = part.split(':').also { assertEquals("$id $part", 2, it.size) }
                assertTrue("$id portion key $key", key in portionKeys)
                assertTrue("$id $part", (amount.toIntOrNull() ?: 0) > 0)
                amount.toInt()
            }
            if (portions.isNotEmpty()) assertTrue("$id default portion $portion in $portions", portion in portions)
        }
    }

    @Test
    fun everyModelClassIsAVisualFood() {
        // The model's labels (food_model.json) and class list (tools/food-model/classes.csv) live on the food-model
        // branch; once merged, every label except _not_food must be a food with visual = 1, and the reverse.
        val labels = findRepoFile("app/src/main/assets/food/food_model.json")?.readText(Charsets.UTF_8)?.let { json ->
            val list = Regex("\"labels\"\\s*:\\s*\\[(.*?)]", RegexOption.DOT_MATCHES_ALL).find(json)?.groupValues?.get(1)
            assertNotNull("food_model.json has no labels", list)
            Regex("\"([^\"]+)\"").findAll(list!!).map { it.groupValues[1] }.toList()
        }
        val classes = findRepoFile("tools/food-model/classes.csv")?.readLines(Charsets.UTF_8)?.drop(1)
            ?.filter { it.isNotBlank() }?.map { it.substringBefore(',').trim() }
        val visual = rows.filter { it.getValue("visual") == "1" }.map { it.getValue("id") }.toSet()
        val ids = rows.map { it.getValue("id") }.toSet()
        for (list in listOfNotNull(labels, classes)) {
            val modelIds = list.filter { it != "_not_food" }.toSet()
            assertTrue("model classes missing from foods.tsv: ${modelIds - ids}", (modelIds - ids).isEmpty())
            assertTrue("model classes with visual = 0: ${modelIds - visual}", (modelIds - visual).isEmpty())
            assertTrue("visual = 1 but not a model class: ${visual - modelIds}", (visual - modelIds).isEmpty())
        }
    }

    @Test
    fun everyFoodAndGroupHasAnEnglishAndSpanishName() {
        val names = repoFile("tools/i18n/src/master/97_foods.txt").readLines(Charsets.UTF_8)
            .filter { it.startsWith("food_") }
            .associate { line ->
                val (key, value) = line.split(" = ", limit = 2)
                val (en, es) = value.split(" ||| ")
                key to (en.trim() to es.trim())
            }
        val string = R.string::class.java
        val keys = rows.map { "food_${it.getValue("id")}" } + groups.map { "food_group_$it" }
        for (key in keys) {
            val (en, es) = names[key] ?: error("no $key in 97_foods.txt")
            assertTrue(key, en.isNotEmpty() && es.isNotEmpty())
            assertNotNull("$key not generated into strings.xml", runCatching { string.getField(key) }.getOrNull())
        }
    }
}
